// 結構体 Config: プログラムの設定値を格納する
struct Config {
    string DATA_DIR = "data";  // 設定ディレクトリパス
    struct DB_CONFIG {         // 数据库配置结构体
        string drivername = "postgresql";  // 驾驶员名称
        string username = "user";          // 用户名
        string password = "pass";          // 密码
        string host = "localhost";         // 主机地址
        string database = "analysis_db";   // 数据库名称
    } db_config;                       // 数据库配置实例
};

// 関数 initialize_logging(): ログ設定を行う
void initialize_logging() {
    // 省略（C++でのログ設定例）
    freopen("processing.log", "w", stdout);  // 出力先をログファイルに指定
}

// 関数 load_files(const string& data_dir): 指定されたディレクトリ内のCSV/JSONファイルを読み込む
vector<string> load_files(const string& data_dir) {
    vector<string> files;                   // ファイルパスを格納するベクトル
    for (const auto& entry : filesystem::directory_iterator(data_dir)) {  // ディレクトリ内のエントリをイテロール
        const string& path = entry.path();   // エントリのパスを取得
        if (path.ends_with(".csv") || path.ends_with(".json")) {         // CSVまたはJSONファイルの場合
            files.push_back(path);           // ファイルパスをベクトルに追加
        }
    }
    return files;                           // ファイルパスのリストを返す
}

// 関数 read_csv_or_json(const vector<string>& files): CSV/JSONファイルを読み込んでデータフレームを作成する
vector<vector<string>> read_csv_or_json(const vector<string>& files) {
    vector<vector<string>> dataframes;      // データフレームのリスト
    for (const string& file : files) {       // 各ファイルに対して
        vector<string> df;                   // 各データフレーム
        ifstream ifs(file);                  // ファイルを読み込む
        if (!ifs) continue;                 // 読み込み失敗時はスキップ
        string line;                        // ラインごとの文字列
        while (getline(ifs, line)) {         // 各ラインを読み込む
            df.push_back(line);              // データフレームに追加
        }
        dataframes.push_back(df);            // データフレームリストに追加
    }
    return dataframes;                       // データフレームのリストを返す
}

// 関数 clean_dataframes(const vector<vector<string>>& dataframes): データフレームのクリーニングを行う
vector<vector<string>> clean_dataframes(const vector<vector<string>>& dataframes) {
    vector<vector<string>> cleaned_dfs = dataframes;  // クリーニング済みデータフレームを格納するベクトル
    for (auto& df : cleaned_dfs) {                  // 各データフレームに対して
        if (df.empty()) continue;                   // 空の場合は処理をスキップ
        // 重複除去: 指定したカラムに基づいて重複行を削除
        set<pair<string, string>> seen;             // 見たことがある行を格納するセット
        vector<string> unique_df;                   // 独特な行を格納するベクトル
        for (const string& row : df) {              // 各行に対して
            if (!row.empty() && seen.find(make_pair(row[0], row[1])) == seen.end()) {  // 重複でない場合
                seen.insert(make_pair(row[0], row[1]));  // 見たことリストに追加
                unique_df.push_back(row);           // 独特な行を追加
            }
        }
        df = unique_df;                            // データフレームを更新
    }
    return cleaned_dfs;                            // クリーニング済みデータフレームのリストを返す
}

// 関数 process_dataframes(const vector<vector<string>>& dataframes): データフレームから統計情報を取得する
void process_dataframes(const vector<vector<string>>& dataframes) {
    for (const auto& df : dataframes) {            // 各データフレームに対して
        if (df.empty()) continue;                  // 空の場合は処理をスキップ
        // 統計処理: 平均応答時間、顧客満足度、トップカテゴリ、レコード数を取得する
        double avg_response_time = 0.0;            // 平均応答時間
        int customer_satisfaction = 0;             // 訪問者満足度
        string top_category;                       // トップカテゴリ
        size_t total_records = df.size();          // レコードの総数

        for (const string& row : df) {             // 各行に対して
            istringstream iss(row);                // 行を文字列として解析するストリーム
            vector<string> cols;                    // 列を格納するベクトル
            string col;                            // 現在の列
            while (getline(iss, col, ',')) {        // , を区切りにして各列を取得
                cols.push_back(col);                // 列をベクトルに追加
            }
            if (!cols.empty()) {                   // 列が空でない場合
                avg_response_time += stod(cols[2]); // 答案時間を追加（例: 列3）
                customer_satisfaction = stoi(cols[3]);  // 満足度を取得（例: 列4）
                top_category = cols[4];            // カテゴリを取得（例: 列5）
            }
        }
        avg_response_time /= total_records;        // 平均応答時間を計算
        cout << "Average Response Time: " << avg_response_time << endl;  // 平均応答時間を出力
        cout << "Customer Satisfaction: " << customer_satisfaction << endl;  // 満足度を出力
        cout << "Top Category: " << top_category << endl;  // トップカテゴリを出力
        cout << "Total Records: " << total_records << endl << endl;  // レコード数を出力
    }
}

// 関数 main(): プログラムのメイン実行部分
int main() {
    initialize_logging();                        // ログ設定を行う
    Config config;                               // 設定値を格納する構造体

    // ファイル読み込み: 指定されたディレクトリ内のファイルを読み込む
    vector<string> files = load_files(config.DATA_DIR);  // ファイルパスのリストを取得

    // データフレーム作成: 読み込んだファイルからデータフレームを作成する
    vector<vector<string>> dataframes = read_csv_or_json(files);  // データフレームのリストを取得

    // データクリーニング: データフレームのクリーニングを行う
    vector<vector<string>> cleaned_dfs = clean_dataframes(dataframes);  // クリーニング済みデータフレームを取得

    // データ分析: クリーニングされたデータフレームから統計情報を取得する
    process_dataframes(cleaned_dfs);  // 統計処理を行う
```

### 各関数の説明

1. **Config構造体**:
   - プログラムの設定値を格納する。
